// Native regression tests for the exact firmware clock implementation.
#include "../wled00/FX_time.h"
#include <assert.h>
#include <stdio.h>
#include <type_traits>

static uint64_t distance(uint64_t a, uint64_t b) { return a > b ? a - b : b - a; }

int main() {
  static_assert(std::is_trivially_copyable<EffectClocks>::value, "Segment copies clocks by value");
  static_assert(sizeof(EffectClocks) <= 104, "Keep segment RAM overhead bounded");
  // Long uptime, all adjacent slider values, fast/slow and stopped. Changing a
  // rate with no elapsed time must never change a single bit of the phase.
  for (uint32_t speed = 0; speed < 256; ++speed) {
    EffectClocks clocks;
    const uint32_t now = 0xD1234567;
    uint64_t before = clocks.advance(now, speed, 1, 0, now);
    assert(clocks.advance(now, (speed + 1) & 255, 1, 0, now) == before);
    assert(clocks.advance(now + 25, (speed + 1) & 255, 1, 0, now) - before == (uint64_t(25 * ((speed + 1) & 255)) << 32));
    before = clocks.advance(now + 25, 0, 1, 0, now);
    assert(clocks.advance(now + 2000, 0, 1, 0, now) == before);
    assert(clocks.advance(now + 2000, 255, 1, 0, now) == before);
    assert(clocks.advance(now + 2001, 255, 1, 0, now) - before == (uint64_t(255) << 32));
  }
  // Constant-rate compatibility for periods used by wipe/scan and sub-ms audio
  // schedulers. Bound the rounding error in phase, independently of frame rate.
  const uint32_t periods[] = {1U, 7U, 128U, 750U, 39000U, 15300000U};
  for (uint32_t period : periods) {
    EffectClocks clocks;
    const uint32_t seed = 123456789;
    uint64_t initial = clocks.advance(seed, 1, period, 0, seed);
    uint32_t elapsed = 0;
    for (unsigned frame = 0; frame < 50000; ++frame) {
      elapsed += 1 + frame % 97;
      const uint64_t actual = clocks.advance(seed + elapsed, 1, period, 0, seed);
      const uint64_t expected = initial + ((uint64_t(elapsed) << 32) / period);
      assert(distance(actual, expected) <= uint64_t(frame) + 2);
    }
  }
  // Period edits retain an already-running timer's fraction, even when the old
  // elapsed time would exceed the new period in an absolute-time implementation.
  EffectClocks timers;
  assert(!timers.due(1000, 1000));
  assert(!timers.due(1400, 1000));
  assert(!timers.due(1400, 100));
  assert(!timers.due(1450, 100));
  assert(timers.due(1461, 100));
  assert(!timers.due(1461, 100));
  assert(!timers.due(2461, 100, 0, false));
  assert(!timers.due(2461, 100));
  assert(timers.due(2562, 100));
  // No off-by-one frame at rational rates (1/3, 1/6, etc.).
  for (uint32_t period = 1; period <= 512; ++period) {
    EffectClocks cadence;
    assert(!cadence.due(0, period));
    for (uint32_t frame = 1; frame <= period * 3; ++frame) {
      assert(cadence.due(frame, period) == (frame % period == 0));
    }
  }
  // Unsigned time rollover, independent channels and segment-transition copies.
  EffectClocks clocks;
  uint64_t before = clocks.advance(0xFFFFFFF0, 3, 1, 0, 0);
  assert(clocks.advance(0x10, 3, 1, 0, 0) - before == (uint64_t(96) << 32));
  const uint64_t saved = clocks.phase[0];
  for (unsigned channel = 1; channel < EffectClocks::CHANNELS; ++channel) {
    clocks.advance(100, channel, 1, channel, 0);
    clocks.advance(101, channel, 1, channel, 0);
    assert(clocks.phase[channel] == (uint64_t(channel) << 32));
    assert(clocks.phase[0] == saved);
  }
  EffectClocks oldEffect = clocks;
  clocks.advance(0x20, 20, 1, 0, 0);
  assert(oldEffect.phase[0] == saved);
  clocks.reset();
  assert(clocks.advance(5000, 1, 100, 0, 0) == 0);
  assert(clocks.advance(5000, 1, 0, 0, 0) == 0);
  assert(clocks.advance(5000, 1, 1, EffectClocks::CHANNELS, 0) == 0);
  // Particle velocity survives small slider edits and a stop/resume round trip.
  EffectVelocity velocity;
  int8_t x = 17, y = -9;
  velocity.reset(x, y, 128);
  uint8_t previousSpeed = 128;
  for (unsigned speed = 128; speed < 256; ++speed) {
    velocity.apply(x, y, uint8_t(speed), previousSpeed);
    assert(x == EffectVelocity::scaled(17, uint8_t(speed), 128));
    assert(y == EffectVelocity::scaled(-9, uint8_t(speed), 128));
    previousSpeed = uint8_t(speed);
  }
  velocity.apply(x, y, 0, previousSpeed);
  assert(x == 0 && y == 0);
  velocity.apply(x, y, 128, 0);
  assert(x == 17 && y == -9);
  x = -17; // the physics engine bounced the particle
  velocity.apply(x, y, 128, 128);
  assert(x == -17 && y == -9);
  velocity.apply(x, y, 64, 128);
  assert(x == -9 && y == -5);
  printf("Effect clock regressions passed; %zu bytes per segment\n", sizeof(EffectClocks));
}
